  cudaFree(d_walkers_hess);
  cudaFree(d_spline_coefs);
  cudaFree(d_a);
  cudaFree(d_b);
  cudaFree(d_c);
  cudaFree(d_da);
  cudaFree(d_db);
  cudaFree(d_dc);
  cudaFree(d_d2a);
  cudaFree(d_d2b);
  cudaFree(d_d2c);
  return 0;
}

